/**
 * LIGHTHOUSE OPTIMIZATION SCRIPT
 * Reduz FCP/LCP via CSS posteragado e otimização de imagens
 * Minificado e otimizado para máxima performance
 */

(function () {
  // 1. Garantir CSS carregue rapidamente
  var ls = document.querySelectorAll('link[rel="preload"][as="style"]');
  for (var i = 0; i < ls.length; i++) {
    if (!ls[i].href.includes('custom') && !ls[i].href.includes('chirpy')) {
      ls[i].media = 'print';
      ls[i].addEventListener('load', function () {
        this.media = 'all';
      });
    }
  }

  // 2. Otimizar imagens: adicionar fetchpriority aos critérios
  document.addEventListener('DOMContentLoaded', function () {
    // Adicionar decoding async a todas imagens
    var imgs = document.querySelectorAll('img');
    for (var j = 0; j < imgs.length; j++) {
      imgs[j].decoding = 'async';
      // Adicionar loading lazy se não tiver
      if (!imgs[j].hasAttribute('loading')) {
        imgs[j].loading = 'lazy';
      }
    }
  });

  // 3. Preload primeira imagem (LCP)
  if (!document.querySelector('link[rel="preload"][as="image"]')) {
    var preload = document.createElement('link');
    preload.rel = 'preload';
    preload.as = 'image';
    var firstImg = document.querySelector('.preview-img img');
    if (firstImg && firstImg.src) {
      preload.href = firstImg.src;
      if (firstImg.srcset) {
        preload.imagesrcset = firstImg.srcset;
      }
      if (firstImg.sizes) {
        preload.imagesizes = firstImg.sizes;
      }
      document.head.appendChild(preload);
    }
  }

  // 4. Monitorar Core Web Vitals em dev
  if (
    window.location.hostname === 'localhost' ||
    window.location.hostname === '127.0.0.1'
  ) {
    window.addEventListener('load', function () {
      if (window.performance && window.performance.getEntriesByType) {
        var fp = performance.getEntriesByName('first-paint');
        var fcp = performance.getEntriesByName('first-contentful-paint');
        if (fp.length > 0 || fcp.length > 0) {
          console.log('Performance:', {
            FP: fp.length > 0 ? Math.round(fp[0].startTime) + 'ms' : 'N/A',
            FCP: fcp.length > 0 ? Math.round(fcp[0].startTime) + 'ms' : 'N/A',
          });
        }
      }
    });
  }
})();
